-- v96: 数学题库批量扩充 70题 → 约90题，覆盖10大模块主要知识点
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status, knowledge_points) VALUES
-- === 集合 (6题) ===
('数学[职高]',NULL,'SINGLE_CHOICE','已知集合A={1,2,3},B={2,3,4},则A∩B=','["A. {1,2,3,4}","B. {1,4}","C. {2,3}","D. {1}"]','C','两集合的交集是公共元素组成的集合，{1,2,3}∩{2,3,4}={2,3}。',1,1,'["集合","交集"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','已知集合A={x|x>0},B={x|x<5},则A∪B=','["A. R","B. {x|0<x<5}","C. {x|x>0}","D. {x|x<5}"]','A','A∪B表示大于0或小于5的所有实数，即全体实数R。',2,1,'["集合","并集"]'),
('数学[职高]',NULL,'TRUE_FALSE','空集是任何集合的子集。','["A. √","B. ×"]','A','空集∅不含任何元素，按规定空集是所有集合的子集。',1,1,'["集合","空集"]'),
('数学[职高]',NULL,'FILL_IN','已知全集U={1,2,3,4,5},A={1,3,5},则∁ᵤA=_______','[]','{2,4}','补集∁ᵤA是从全集U中去掉A的元素，即{2,4}。',2,1,'["集合","补集"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','"x>3"是"x>5"的什么条件？','["A. 充分不必要","B. 必要不充分","C. 充要","D. 既不充分也不必要"]','B','x>5⇒x>3成立（必要性），但x>3不能推出x>5（如x=4），所以是必要不充分条件。',3,1,'["集合","充要条件"]'),
('数学[职高]',NULL,'FILL_IN','集合{x|-2≤x<3}用区间表示为_______','[]','[-2,3)','闭区间[-2,3)表示-2≤x<3。包含端点用[，不包含用)。',1,1,'["集合","区间"]'),
-- === 不等式 (5题) ===
('数学[职高]',NULL,'SINGLE_CHOICE','不等式x²-4x+3<0的解集是','["A. {x|x<1或x>3}","B. {x|1<x<3}","C. {x|x<3}","D. {x|x>1}"]','B','因式分解(x-1)(x-3)<0，开口向上的抛物线在两根之间为负，故1<x<3。',2,1,'["不等式","一元二次不等式"]'),
('数学[职高]',NULL,'FILL_IN','不等式|2x-1|≤3的解集为_______','[]','[-1,2]','|2x-1|≤3⇔-3≤2x-1≤3⇔-2≤2x≤4⇔-1≤x≤2。',2,1,'["不等式","绝对值"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','若a>b>0，则下列不等式成立的是','["A. a²<b²","B. 1/a>1/b","C. a²>b²","D. a<b"]','C','正数时平方保持大小关系，a>b>0⇒a²>b²。',1,1,'["不等式","不等式性质"]'),
('数学[职高]',NULL,'FILL_IN','不等式组{x>2, x≤5}的解集用区间表示为_______','[]','(2,5]','x>2即(2,+∞)，x≤5即(-∞,5]，取交集得(2,5]。',1,1,'["不等式","不等式组"]'),
('数学[职高]',NULL,'TRUE_FALSE','不等式x²+1<0有实数解。','["A. √","B. ×"]','B','x²≥0恒成立，故x²+1≥1>0，不等式x²+1<0无实数解。',2,1,'["不等式","无解判断"]'),
-- === 函数 (8题) ===
('数学[职高]',NULL,'FILL_IN','函数f(x)=√(x-2)的定义域为_______','[]','[2,+∞)','被开方式x-2≥0，即x≥2。定义域为[2,+∞)。',2,1,'["函数","定义域"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','下列函数中，是奇函数的是','["A. y=x²","B. y=x³","C. y=|x|","D. y=cosx"]','B','奇函数满足f(-x)=-f(x)。x³满足(-x)³=-x³。',2,1,'["函数","奇偶性"]'),
('数学[职高]',NULL,'TRUE_FALSE','函数f(x)=x²在R上是增函数。','["A. √","B. ×"]','B','f(x)=x²在(-∞,0]上递减，在[0,+∞)上递增，在R上不是单调函数。',1,1,'["函数","单调性"]'),
('数学[职高]',NULL,'FILL_IN','已知f(x)=2x+1，则f(3)=_______','[]','7','代入x=3：f(3)=2×3+1=7。',1,1,'["函数","函数值"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','二次函数y=(x-2)²+3的顶点坐标是','["A. (-2,3)","B. (2,3)","C. (-2,-3)","D. (2,-3)"]','B','顶点式y=a(x-h)²+k的顶点为(h,k)。这里h=2,k=3，顶点(2,3)。',2,1,'["函数","二次函数","顶点"]'),
('数学[职高]',NULL,'FILL_IN','函数y=x²-4x+6的最小值为_______','[]','2','配方：y=(x-2)²+2，顶点(2,2)，最小值=2。',3,1,'["函数","二次函数","最值"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','若f(x)是偶函数且f(2)=5，则f(-2)=','["A. -5","B. 5","C. -2","D. 2"]','B','偶函数f(-x)=f(x)，故f(-2)=f(2)=5。',1,1,'["函数","奇偶性"]'),
('数学[职高]',NULL,'TRUE_FALSE','函数y=1/x的定义域是{x|x≠0}。','["A. √","B. ×"]','A','分母不能为零，所以x≠0。',1,1,'["函数","定义域"]'),
-- === 三角函数 (7题) ===
('数学[职高]',NULL,'FILL_IN','sin30°=_______','[]','1/2','特殊角三角函数值：sin30°=1/2。',1,1,'["三角函数","特殊角"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','已知sinα=3/5，α是锐角，则cosα=','["A. 3/5","B. 4/5","C. -3/5","D. -4/5"]','B','由sin²α+cos²α=1，cosα=√(1-9/25)=√(16/25)=4/5。',2,1,'["三角函数","同角关系"]'),
('数学[职高]',NULL,'FILL_IN','tan45°=_______','[]','1','特殊角三角函数值：tan45°=1。',1,1,'["三角函数","特殊角"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','函数y=sinx的最小正周期是','["A. π","B. 2π","C. π/2","D. 4π"]','B','正弦函数y=sinx的最小正周期为2π。',1,1,'["三角函数","周期"]'),
('数学[职高]',NULL,'FILL_IN','cos60°=_______','[]','1/2','特殊角三角函数值：cos60°=1/2。',1,1,'["三角函数","特殊角"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','在△ABC中，a=3,b=4,C=90°，则c=','["A. 5","B. 7","C. √7","D. 25"]','A','由勾股定理c²=a²+b²=9+16=25，c=5。',2,1,'["三角函数","解三角形"]'),
('数学[职高]',NULL,'TRUE_FALSE','sin(180°-α)=sinα。','["A. √","B. ×"]','A','诱导公式：sin(π-α)=sinα，正确。',2,1,'["三角函数","诱导公式"]'),
-- === 数列 (6题) ===
('数学[职高]',NULL,'FILL_IN','等差数列中，a₁=2,d=3,则a₅=_______','[]','14','通项公式aₙ=a₁+(n-1)d，a₅=2+(5-1)×3=2+12=14。',1,1,'["数列","等差数列","通项"]'),
('数学[职高]',NULL,'FILL_IN','等差数列2,5,8,...的前10项和S₁₀=_______','[]','155','a₁=2,d=3。Sₙ=n[2a₁+(n-1)d]/2。S₁₀=10[4+27]/2=10×31/2=155。',3,1,'["数列","等差数列","求和"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','已知等比数列{an}中，a₁=2,q=3，则a₃=','["A. 6","B. 12","C. 18","D. 8"]','C','通项aₙ=a₁qⁿ⁻¹，a₃=2×3²=2×9=18。',2,1,'["数列","等比数列","通项"]'),
('数学[职高]',NULL,'TRUE_FALSE','等差数列的公差可以是负数。','["A. √","B. ×"]','A','公差d可以是正数、零或负数。d<0时数列递减。',1,1,'["数列","等差数列"]'),
('数学[职高]',NULL,'FILL_IN','等比数列1,2,4,...的公比q=_______','[]','2','公比q=后项/前项，2/1=4/2=2。',1,1,'["数列","等比数列","公比"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','等差数列-3,0,3,6,...的公差是','["A. -3","B. 0","C. 3","D. 6"]','C','公差d=后项-前项，0-(-3)=3。',1,1,'["数列","等差数列","公差"]'),
-- === 平面向量 (4题) ===
('数学[职高]',NULL,'FILL_IN','已知向量a=(3,4)，则|a|=_______','[]','5','向量模|a|=√(3²+4²)=√25=5。',1,1,'["平面向量","模"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','已知a=(1,2),b=(3,4),则a+b=','["A. (3,6)","B. (4,6)","C. (4,5)","D. (2,2)"]','B','向量加法对应坐标相加：(1+3,2+4)=(4,6)。',1,1,'["平面向量","加法"]'),
('数学[职高]',NULL,'FILL_IN','已知a·b=6,|a|=2,|b|=5,则cos<a,b>=_______','[]','0.6','cos<a.b>=(a,b)/(|a|,|b|)=6/(2×5)=6/10=0.6。',2,1,'["平面向量","数量积"]'),
('数学[职高]',NULL,'TRUE_FALSE','若向量a=(2,1),b=(-4,-2),则a与b共线。','["A. √","B. ×"]','A','b=-2a，向量成比例关系，即共线。',2,1,'["平面向量","共线"]'),
