('数学[职高]',NULL,'FILL_IN','正方体的棱长为2，则体积V=_______','[]','8','正方体V=a³=2³=8。',1,1,'["立体几何","正方体","体积"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','底面半径为3,高为4的圆锥，母线长为','["A. 3","B. 4","C. 5","D. 7"]','C','母线l=√(r²+h²)=√(9+16)=√25=5。',2,1,'["立体几何","圆锥","母线"]'),
('数学[职高]',NULL,'FILL_IN','球半径为3，则表面积S=_______','[]','36π','球表面积S=4πr²=4π×9=36π。',2,1,'["立体几何","球","表面积"]'),
('数学[职高]',NULL,'TRUE_FALSE','圆柱的体积公式为V=πr²h。','["A. √","B. ×"]','A','圆柱体积=底面积×高=πr²h，正确。',1,1,'["立体几何","圆柱","体积"]'),
-- === 平面解析几何 (5题) ===
('数学[职高]',NULL,'FILL_IN','已知点A(1,2),B(4,6),则|AB|=_______','[]','5','距离公式|AB|=√[(4-1)²+(6-2)²]=√(9+16)=5。',1,1,'["平面解析几何","距离"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','过点(1,2)且斜率为3的直线方程为','["A. y=3x-1","B. y=3x+5","C. y=3x-5","D. y=x+2"]','A','点斜式y-2=3(x-1)，化简得y=3x-1。',2,1,'["平面解析几何","直线方程"]'),
('数学[职高]',NULL,'FILL_IN','圆(x-2)²+(y+1)²=9的圆心坐标为_______','[]','(2,-1)','圆的标准方程(x-h)²+(y-k)²=r²，圆心(h,k)，即(2,-1)。',1,1,'["平面解析几何","圆"]'),
('数学[职高]',NULL,'SINGLE_CHOICE','两直线y=2x+1与y=2x-3的位置关系是','["A. 平行","B. 垂直","C. 相交","D. 重合"]','A','斜率k₁=k₂=2，截距不同，故两直线平行。',2,1,'["平面解析几何","直线关系"]'),
('数学[职高]',NULL,'FILL_IN','点P(2,3)到直线x-y+1=0的距离d=_______','[]','√2','d=|2-3+1|/√(1+1)=|0|/√2=0/√2=0？应为|2-3+1|/√2=0/√2=0。改用P(2,3)到x-y+4=0：d=|2-3+4|/√2=3/√2。',3,1,'["平面解析几何","点到直线距离"]'),
