('数学[职高]',NULL,'SINGLE_CHOICE','掷一枚骰子，出现偶数点的概率是','["A. 1/6","B. 1/3","C. 1/2","D. 2/3"]','C','偶数点{2,4,6}共3种，总6种，P=3/6=1/2。',1,1,'["概率","古典概型"]'),
('数学[职高]',NULL,'FILL_IN','一组数据：2,4,4,6,8，则平均数为_______','[]','4.8','平均数=(2+4+4+6+8)/5=24/5=4.8。',1,1,'["统计","平均数"]'),
('数学[职高]',NULL,'TRUE_FALSE','必然事件的概率为1。','["A. √","B. ×"]','A','必然事件发生的概率为1，这是概率的公理。',1,1,'["概率","概率定义"]');
